{
  "description": "A single chimeric creature is shown in right-facing profile standing on two legs against a plain light background. The front of the animal, including the head, and the rear including the hind legs and tail, have the appearance of a red fox with dense reddish-orange and white fur, while the mid-body, chest, belly, back and folded wings have the appearance of a barn owl with white, buff, grey and brown mottled plumage. The fox head is held high with pointed ears and a pointed muzzle, the owl wings are folded neatly along the back and sides covering the torso, the fox hind legs are bent and support the upright posture, and a long bushy fox tail hangs behind the legs to the ground.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a fox head at the top front facing right, with reddish-orange fur on the crown and cheeks, white fur on the muzzle, chin and throat, a black nose at the tip of a pointed snout, amber-brown eyes, and white whiskers on the muzzle",
      "where": "at the anterior top of the body on top of the neck"
    },
    {
      "part": "ears",
      "looks_like": "two upright triangular pointed ears with reddish-orange outer fur, black tips and edges, and pale and dark fur inside the ear cup",
      "where": "on top of the head, one more forward and one slightly behind"
    },
    {
      "part": "legs",
      "looks_like": "two muscular hind legs covered in short to medium reddish-brown fox fur with lighter grey-white on the inner thigh and lower leg, bent at the hock joint",
      "where": "under the rear half of the body, extending from the lower torso to the ground"
    },
    {
      "part": "feet",
      "looks_like": "two fox paws with brown fur, rounded toe pads and short dark claws, flat on the ground",
      "where": "at the bottom ends of the two hind legs"
    },
    {
      "part": "tail",
      "looks_like": "one long, thick, bushy tail covered in long reddish-orange fur with a paler whitish tip at the end, tapering slightly",
      "where": "at the rear of the body behind the hind legs, extending down and slightly back to near the ground"
    },
    {
      "part": "wings",
      "looks_like": "two folded wings with layered flight feathers in buff, tan, white and grey-brown, the upper wing coverts mottled with grey and small black-and-white spots, the primary feathers barred with brown and black",
      "where": "along the back and sides of the torso, one wing visible in profile on the near side covering from the shoulder to the lower flank, the far wing tip slightly visible underneath"
    },
    {
      "part": "feathers",
      "looks_like": "dense owl plumage covering the neck, chest, belly, back and wings; chest and belly feathers are white and fluffy with small black dots, neck and back feathers are buff and grey-brown with speckled patterning, wing feathers are broad and layered",
      "where": "covering the entire mid-body from the base of the fox head and neck down over the chest, belly, back and wings, surrounding the fox fur of the legs and tail"
    },
    {
      "part": "markings",
      "looks_like": "small black spots scattered on the white chest and belly, larger dark brown and black speckles and eye-like spots on the grey-brown wing coverts, dark barring on the flight and tail feathers, and the white muzzle/throat contrasting with the reddish-orange face",
      "where": "on the chest, belly, neck, back and wings, and on the face"
    }
  ],
  "attached_objects": [],
  "animals": [
    "fox",
    "barn owl"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
